dsk.args3:
// ==========================================
// ⚙️ GABENVORBEREITER
// NUR DIESEN LINK PRO GABE ANPASSEN
// ==========================================
const macroLink = "@UUID[Compendium.dsk-havena-und-umland.makros.Macro.1tBOnhW6okOKlMd4]{Gabe anwenden}";
// ==========================================

(async () => {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

if (!globalThis.DSK?.Gabe?.DatenErmitteln) {
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Gabe?.DatenErmitteln || !DSK_FW?.QS?.AusTestData)
    return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

// +++ 2 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++

let wirkenderActor =
    (typeof actor !== "undefined" && actor) ||
    (typeof testData !== "undefined" && testData?.speaker?.actor
        ? game.actors.get(testData.speaker.actor) : null) ||
    canvas.tokens.controlled[0]?.actor ||
    game.user.character ||
    null;

if (!wirkenderActor)
    return ui.notifications.warn("Luna sagt 🌙: Ich konnte den Wirkenden nicht finden!");

// +++ 3 - GABENDATEN ++++++++++++++++++++++++++++++++++++++++++

const testDaten = typeof testData !== "undefined" ? testData : null;
const gabe = await DSK_FW.Gabe.DatenErmitteln({
    actor: wirkenderActor,
    testDataObj: testDaten
});

if (!gabe)
    return ui.notifications.error("Luna sagt 🌙: Die Gabendaten konnten nicht ermittelt werden!");

const { vollerName: gabenName, ahne, aepKosten } = gabe;
const iconBild = DSK_FW.Symbol(ahne);

// +++ 4 - AeP + QS ++++++++++++++++++++++++++++++++++++++++++++

const currentAeP = Number(foundry.utils.getProperty(wirkenderActor, "system.stats.AeP.value")) || 0;
let htmlInhalt = "", topHeader = "";

if (currentAeP < aepKosten) {
    topHeader = "Fehlschlag";
    await wirkenderActor.update({ "system.stats.AeP.value": 0 });

    htmlInhalt =
        `<p style="margin-bottom:8px;"><b>${wirkenderActor.name}</b> hat versucht, die Gabe zu wirken.</p>` +
        `<hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">` +
        `<p style="margin-bottom:8px;color:#8b0000;"><b>Fehlschlag!</b> Die Kraft reicht nicht aus.</p>` +
        `<p style="margin-bottom:8px;">Die restlichen <b>${currentAeP} AeP</b> wurden verbraucht, aber die Gabe schlägt fehl.</p>`;
} else {
    topHeader = "Wirkungsbeginn";

    const qs = Math.max(1, DSK_FW.QS.AusTestData(testDaten) || 1);
    await wirkenderActor.setFlag("world", "letzteGabenQS", qs);
    await wirkenderActor.update({ "system.stats.AeP.value": currentAeP - aepKosten });

    htmlInhalt =
        `<p style="margin-bottom:8px;"><b>${wirkenderActor.name}</b> wirkt <b>${gabe.name}</b>.</p>` +
        `<hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">` +
        `<p style="margin-bottom:8px;color:#76301b;"><b>Kosten:</b> Die AeP in Höhe von <b>${aepKosten}</b> sind abgezogen worden.</p>` +
        `<hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">` +
        `<p style="margin-bottom:8px;">Klicke hier, um die Gabe anzuwenden:</p>` +
        `<span style="font-size:15px;">${macroLink}</span>`;
}

// +++ 5 - CHATKARTE +++++++++++++++++++++++++++++++++++++++++++

const contentHtml =
    `<div style="font-family:'Signika',sans-serif;">` +
        `<div class="dskbox1">` +
            `<p style="display:flex;gap:8px;align-items:center;margin:0;white-space:nowrap;">` +
                `<img src="${iconBild}" style="width:28px;height:28px;border:none;background:transparent;flex-shrink:0;">` +
                `<b style="font-size:1.05em;">${topHeader}</b>` +
            `</p>` +
            `<p style="font-weight:bold;margin-top:6px;margin-bottom:0;">${gabenName}</p>` +
        `</div>` +
        `<div class="dskbox2" style="margin-top:10px;text-align:center;">${htmlInhalt}</div>` +
    `</div>`;

const msg = await ChatMessage.create({
    speaker: { alias: "System" },
    content: contentHtml
});

if (currentAeP >= aepKosten && msg)
    await wirkenderActor.setFlag("world", "letzteGabenMessageId", msg.id);

})();
